use vstd::prelude::*;

verus! {

spec fn seq_u8_bitand(a: Seq<u8>, b: Seq<u8>) -> Seq<u8>
    recommends
        a.len() == b.len(),
    decreases a.len(),
{
    if a.len() == 0 {
        Seq::<u8>::empty()
    } else {
        seq![a[0] & b[0]] + seq_u8_bitand(a.drop_first(), b.drop_first())
    }
}

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (out: Vec<u8>)
    requires
        a@.len() == b@.len(),
    ensures
        out@ == seq_u8_bitand(a@, b@),
{
    assert_eq!(a.len(), b.len(), "input vectors must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}

} // verus!

